"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["5304"],{80338(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fases_com_precedencia_no_mesmo_momento","status":422,"titulo":"Fases ligadas por preced\xeancia n\xe3o podem estar no mesmo momento"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fases_com_precedencia_no_mesmo_momento","requisitos":["UNI-REQ-0485"],"oQueAconteceu":["O cadastro de fases diz que certas fases v\xeam antes de outras: por exemplo,\\n`RESULTADO_FINAL` antes de `HABILITACAO`. Quando o edital marca uma fase com \\"no\\nmesmo momento da anterior\\" (UNI-REQ-0485), ela passa a acontecer no mesmo momento\\nda fase que vem antes na lista. Se as duas fases ficam no mesmo momento e o\\ncadastro de preced\xeancia p\xf5e uma antes da outra, a ordem do cadastro deixa de\\nvaler, e a recusa sai com **422**.","Os c\xf3digos das duas fases v\xeam do cadastro de preced\xeancia, e n\xe3o do que a pessoa\\ndigitou. A mensagem da resposta diz: \\"A fase \'*c\xf3digoAntecessora*\' vem antes da fase\\n\'*c\xf3digoSucessora*\' no cadastro de preced\xeancia, e as duas est\xe3o marcadas para\\nacontecer no mesmo momento. Retire a marca \\"no mesmo momento da anterior\\" que junta\\nas duas ou separe-as na ordem do cronograma.\\" A recusa fica na fase de maior\\nordem. Vale tamb\xe9m para a primeira e a terceira fase de um grupo no mesmo momento,\\nmesmo sem serem vizinhas.","Se a ordem do cronograma est\xe1 invertida em rela\xe7\xe3o ao cadastro **e** a marca junta\\nas duas fases, vale esta recusa, e n\xe3o a de\\n[`precedencia_fase_violada`](/erros/uniplus.selecao.processo_seletivo.precedencia_fase_violada).\\nQuando a ordem est\xe1 invertida e as duas fases n\xe3o est\xe3o juntas pela marca, a\\nrecusa continua sendo a de preced\xeancia violada.","O campo da recusa depende da opera\xe7\xe3o:","- ao definir o cronograma (`PUT`), \xe9 `fases[i].noMesmoMomentoDaAnterior`, sem\\n  identificadores;\\n- na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, \xe9\\n  `/cronograma/fases/{i}/noMesmoMomentoDaAnterior`, com o c\xf3digo da fase em\\n  `identificadores`, no formato `[{\\"lista\\": \\"fases\\", \\"identificador\\": \\"<c\xf3digo da fase>\\"}]`.","A rela\xe7\xe3o de preced\xeancia pode ser cadastrada depois de o cronograma ser gravado;\\npor isso a confer\xeancia \xe9 feita de novo na publica\xe7\xe3o. Nada \xe9 gravado, e o\\ncronograma anterior continua como estava."],"comoResolver":["Escolha uma das sa\xeddas e envie de novo:","- retire a marca \\"no mesmo momento da anterior\\" que junta as duas fases;\\n- ou separe as duas fases na ordem do cronograma, deixando antes a que vem antes\\n  no cadastro."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);